interface.definition:
a!localVariables(
  local!isNewVersion: if(
    a!isNullOrEmpty(ri!ask.createdOn),
    true,
    if(
      todatetime(ri!ask.createdOn) > #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12888338",
      true,
      false
    )
  ),
  local!isOldVersion: if(
    a!isNullOrEmpty(ri!ask.createdOn),
