      false
    )
  ),
  local!selectedTab: 1,
  local!refData: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId: {
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245536",
      #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12926741",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245543",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245550",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5245730",
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3135783",
      "30"
    },
    isActive: true,
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
