  local!nextAssigneeGroup: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6851428"(taskStatusId: local!nextStatusId),
  local!assignee: if(
    a!isNullOrEmpty(local!nextAssigneeGroup),
    null,
    a!groupMembers(local!nextAssigneeGroup)
  ),
  local!assigneeId: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(
      index(local!assignee, "totalCount", null)
    ),
    null,
    if(
      local!assignee.totalCount > 1,
      if(
        toboolean(local!isOldVersion) = true,
        property(
          #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
            description: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(local!nextAssigneeGroup),
            refTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177789"
          ).data,
          "refId",
          null
        ),
        property(
          #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
            description: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(local!nextAssigneeGroup),
            refTypeId: #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11818616"
          ).data,
          "refId",
          null
        )
      ),
      property(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3070432"(
