      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197132"[3]
    },
    ri!coreAskDetails.levelNeedId
  ),
  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: if(
      ri!isTaskAmend,
