    ) & if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!task.statusId),
      "",
      " : " & local!selectedGroup
    ),
    contents: {
      #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3769972"(
        selectedTab: local!selectedTab,
