        previousCommentsShowWhen: and(
          ri!isEdit = true,
          ri!task.statusId <> #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3165924"
        ),
        isReview: false
      ),
      /*DETAILS*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "ASK Details",
        contents: {
          #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3341961"(task: ri!task),
          #"SYSTEM_SYSRULES_cardLayout"(
            contents: {
              #"SYSTEM_SYSRULES_columnsLayout"(
                columns: {
                  #"SYSTEM_SYSRULES_columnLayout"(
                    contents: {
                      #"SYSTEM_SYSRULES_textField"(
