                              label: "DPP FTE Amount",
                              value: ri!coreAskDetails.fteAmount,
                              saveInto: ri!coreAskDetails.fteAmount,
                              required: true,
                              disabled: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!coreAskDetails.headCountAmount),
                              validations: if(
                                ri!coreAskDetails.headCountAmount < ri!coreAskDetails.fteAmount,
