                  )
                },
                stackWhen: { "PHONE", "TABLET_PORTRAIT" }
              ),
              #"SYSTEM_SYSRULES_paragraphField"(
                label: "Role Summary *",
                helpTooltip: "Overview of the basic function and purpose of the job.",
                value: ri!coreAskDetails.roleSummary,
                saveInto: ri!coreAskDetails.roleSummary,
                characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3426796",
